import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=mid',{waitUntil:'domcontentloaded',timeout:25000}).catch(()=>{})
await pg.waitForTimeout(2500)
const info=await pg.evaluate(()=>{
  const cb=document.querySelector('.choice-b')
  const fbl=[...document.querySelectorAll('.field-block-label')].find(e=>/树木倾倒数量/.test(e.textContent))
  const choice=document.querySelector('.choice')
  const fblock=fbl? fbl.closest('.field-block'):null
  const cs=el=>el?{fs:getComputedStyle(el).fontSize, fw:getComputedStyle(el).fontWeight, lh:getComputedStyle(el).lineHeight}:null
  let gap=null
  if(choice&&fblock){ const cr=choice.getBoundingClientRect(); const fr=fblock.getBoundingClientRect(); gap=Math.round(fr.top-cr.bottom) }
  return { choiceB:cs(cb), fieldBlockLabel:cs(fbl), gapChoiceToField:gap, choiceMarginBottom: choice?getComputedStyle(choice).marginBottom:null, fblockMarginTop: fblock?getComputedStyle(fblock).marginTop:null }
})
console.log(JSON.stringify(info,null,2))
await b.close()

