  const fblock=card.querySelector('.field-block')
  const g=el=>el?{fs:getComputedStyle(el).fontSize,fw:getComputedStyle(el).fontWeight}:null
  const cb=card.querySelector('.choice-b')
  const sub=card.querySelector('.choice-sub')
  const fbl=card.querySelector('.field-block-label')
  const cr=choice.getBoundingClientRect(), fr=fblock.getBoundingClientRect()
  return {
    choiceB:g(cb), sub:g(sub), fieldBlockLabel:g(fbl),
    gap_toggle_to_fieldblock: Math.round(fr.top-cr.bottom),
    choiceMarginTop:getComputedStyle(choice).marginTop,
    choiceMarginBottom:getComputedStyle(choice).marginBottom,
    fblockMarginTop:getComputedStyle(fblock).marginTop
  }
})
console.log(JSON.stringify(info,null,2))
await b.close()

